patch:
diff --git a/spec/scripts/verdict.js b/spec/scripts/verdict.js
index b43f7f2..5c3ca83 100644
--- a/spec/scripts/verdict.js
+++ b/spec/scripts/verdict.js
@@ -410,6 +410,12 @@ if (ledger) {
   // D1/D2: retention is additive to the printed row above — it never changes row's shape or
   // adds a third stdout line (D4). Reached only when profile !== 'release' (rejected earlier, D3).
   if (retainDir) {
+    // killed-finding evidence strings are the bulk of a large workflow return; strip them from
+    // the retained copy so the artifact stays lean (the count already lives in the printed row's
+    // findings.killed) while survivors — the ones still open — keep their evidence intact.
+    const reviewer = workflow && Array.isArray(workflow.killed)
+      ? { ...workflow, killed: workflow.killed.map(({ evidence, ...rest }) => rest) }
+      : workflow
     const artifact = {
       runId: row.runId,
       ts,
@@ -420,7 +426,7 @@ if (ledger) {
       verdict: word,
       dispositions: { waived, rejected, fixDispatched },
       legs: [...legRows.values()], // verbatim manifest rows — observed UNTRUNCATED (D1)
-      reviewer: workflow, // the --workflow file's parsed JSON verbatim, or null (D2)
+      reviewer, // the --workflow file's parsed JSON, or null (D2) — killed[].evidence trimmed above
     }
     writeRetainedArtifact(retainDir, row.runId, artifact)
   }
